package com.civic.controller; import com.civic.entity.*; import com.civic.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController {private final PetitionRepository petitions;private final PollRepository polls;private final SignatureRepository signatures;private final VoteRepository votes;private final UserRepository users;
 @GetMapping("/citizen") public Map<String,Object> citizen(){User u=me();long my=petitions.findAll().stream().filter(p->p.getCreator().getId().equals(u.getId())).count();long signed=signatures.findAll().stream().filter(s->s.getUser().getId().equals(u.getId())).count();long voted=votes.findAll().stream().filter(v->v.getUser().getId().equals(u.getId())).count();long pollsCreated=polls.findByCreatedBy(u).size();return Map.of("myPetitions",my,"signatures",signed,"votes",voted,"pollsCreated",pollsCreated);}
 @GetMapping("/official") public Map<String,Object> official(){User u=me();if(u.getRole()!=Role.OFFICIAL||!u.isVerified()||!u.isActive())throw new RuntimeException("Official account is not verified");List<Petition> ps=petitions.findAll().stream().filter(p->u.getDepartment()!=null&&u.getDepartment().equalsIgnoreCase(p.getDepartment())).toList();List<Poll> po=polls.findAll().stream().filter(p->u.getDepartment()!=null&&u.getDepartment().equalsIgnoreCase(p.getDepartment())).toList();return Map.of("totalPetitions",ps.size(),"activePetitions",ps.stream().filter(p->p.getStatus()==com.civic.enums.PetitionStatus.ACTIVE).count(),"underReview",ps.stream().filter(p->p.getStatus()==com.civic.enums.PetitionStatus.UNDER_REVIEW).count(),"approved",ps.stream().filter(p->p.getStatus()==com.civic.enums.PetitionStatus.APPROVED).count(),"rejected",ps.stream().filter(p->p.getStatus()==com.civic.enums.PetitionStatus.REJECTED).count(),"polls",po.size(),"activePolls",po.stream().filter(p->p.getStatus()==com.civic.enums.PollStatus.ACTIVE).count(),"signatures",ps.stream().mapToLong(Petition::getCurrentSignatures).sum(),"votes",po.stream().mapToLong(p->votes.countByPoll(p)).sum());}
 private User me(){return users.findByEmail(org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}
}
